    /// Runs the PAP on the inputs set.
    pub fn run(&mut self) {
        self.MPARA();
        self.MRE4JL();
        self.VBEZBSO = Dec::ZERO;
        self.MRE4();
        self.MRE4ABZ();
        self.MBERECH();
        self.MSONST();
    }

    fn MPARA(&mut self) {
        self.BBGRVALV = Dec::lit(101400, 0);
        self.AVSATZAN = Dec::lit(13, 3);
        self.RVSATZAN = Dec::lit(93, 3);
        self.BBGKVPV = Dec::lit(69750, 0);
        self.KVSATZAN = self.KVZ.divide_exact(ZAHL2).divide_exact(ZAHL100).add(Dec::lit(7, 2));
        if (self.PVS == 1) {
            self.PVSATZAN = Dec::lit(23, 3);
        } else {
            self.PVSATZAN = Dec::lit(18, 3);
        }
        if (self.PVZ == 1) {
            self.PVSATZAN = self.PVSATZAN.add(Dec::lit(6, 3));
        } else {
            self.PVSATZAN = self.PVSATZAN.subtract(self.PVA.multiply(Dec::lit(25, 4)));
        }
        self.W1STKL5 = Dec::lit(14071, 0);
        self.W2STKL5 = Dec::lit(34939, 0);
        self.W3STKL5 = Dec::lit(222260, 0);
        self.GFB = Dec::lit(12348, 0);
        self.SOLZFREI = Dec::lit(20350, 0);
    }

    fn MRE4JL(&mut self) {
        if (self.LZZ == 1) {
            self.ZRE4J = self.RE4.divide(ZAHL100, 2, Round::Down);
            self.ZVBEZJ = self.VBEZ.divide(ZAHL100, 2, Round::Down);
            self.JLFREIB = self.LZZFREIB.divide(ZAHL100, 2, Round::Down);
            self.JLHINZU = self.LZZHINZU.divide(ZAHL100, 2, Round::Down);
        } else {
            if (self.LZZ == 2) {
                self.ZRE4J = self.RE4.multiply(ZAHL12).divide(ZAHL100, 2, Round::Down);
                self.ZVBEZJ = self.VBEZ.multiply(ZAHL12).divide(ZAHL100, 2, Round::Down);
                self.JLFREIB = self.LZZFREIB.multiply(ZAHL12).divide(ZAHL100, 2, Round::Down);
                self.JLHINZU = self.LZZHINZU.multiply(ZAHL12).divide(ZAHL100, 2, Round::Down);
            } else {
                if (self.LZZ == 3) {
                    self.ZRE4J = self.RE4.multiply(ZAHL360).divide(ZAHL700, 2, Round::Down);
                    self.ZVBEZJ = self.VBEZ.multiply(ZAHL360).divide(ZAHL700, 2, Round::Down);
                    self.JLFREIB = self.LZZFREIB.multiply(ZAHL360).divide(ZAHL700, 2, Round::Down);
                    self.JLHINZU = self.LZZHINZU.multiply(ZAHL360).divide(ZAHL700, 2, Round::Down);
                } else {
                    self.ZRE4J = self.RE4.multiply(ZAHL360).divide(ZAHL100, 2, Round::Down);
                    self.ZVBEZJ = self.VBEZ.multiply(ZAHL360).divide(ZAHL100, 2, Round::Down);
                    self.JLFREIB = self.LZZFREIB.multiply(ZAHL360).divide(ZAHL100, 2, Round::Down);
                    self.JLHINZU = self.LZZHINZU.multiply(ZAHL360).divide(ZAHL100, 2, Round::Down);
                }
            }
        }
        if (self.af == 0) {
            self.f = Dec::of(1);
        }
    }

    fn MRE4(&mut self) {
        if (self.ZVBEZJ.compare_to(Dec::ZERO) == 0) {
            self.FVBZ = Dec::ZERO;
            self.FVB = Dec::ZERO;
            self.FVBZSO = Dec::ZERO;
            self.FVBSO = Dec::ZERO;
        } else {
            if (self.VJAHR < 2006) {
                self.J = 1;
            } else {
                if (self.VJAHR < 2058) {
                    self.J = (self.VJAHR - 2004);
                } else {
                    self.J = 54;
                }
            }
            if (self.LZZ == 1) {
                self.VBEZB = self.VBEZM.multiply(Dec::of(self.ZMVB)).add(self.VBEZS);
                self.HFVB =
                    TAB2[self.J as usize].divide_exact(ZAHL12).multiply(Dec::of(self.ZMVB)).set_scale(0, Round::Up);
                self.FVBZ =
                    TAB3[self.J as usize].divide_exact(ZAHL12).multiply(Dec::of(self.ZMVB)).set_scale(0, Round::Up);
            } else {
                self.VBEZB = self.VBEZM.multiply(ZAHL12).add(self.VBEZS).set_scale(2, Round::Down);
                self.HFVB = TAB2[self.J as usize];
                self.FVBZ = TAB3[self.J as usize];
            }
            self.FVB = self.VBEZB.multiply(TAB1[self.J as usize]).divide_exact(ZAHL100).set_scale(2, Round::Up);
            if (self.FVB.compare_to(self.HFVB) == 1) {
                self.FVB = self.HFVB;
            }
            if (self.FVB.compare_to(self.ZVBEZJ) == 1) {
                self.FVB = self.ZVBEZJ;
            }
            self.FVBSO = self
                .FVB
                .add(self.VBEZBSO.multiply(TAB1[self.J as usize]).divide_exact(ZAHL100))
                .set_scale(2, Round::Up);
            if (self.FVBSO.compare_to(TAB2[self.J as usize]) == 1) {
                self.FVBSO = TAB2[self.J as usize];
            }
            self.HFVBZSO =
                self.VBEZB.add(self.VBEZBSO).divide_exact(ZAHL100).subtract(self.FVBSO).set_scale(2, Round::Down);
            self.FVBZSO = self.FVBZ.add(self.VBEZBSO.divide_exact(ZAHL100)).set_scale(0, Round::Up);
            if (self.FVBZSO.compare_to(self.HFVBZSO) == 1) {
                self.FVBZSO = self.HFVBZSO.set_scale(0, Round::Up);
            }
            if (self.FVBZSO.compare_to(TAB3[self.J as usize]) == 1) {
                self.FVBZSO = TAB3[self.J as usize];
            }
            self.HFVBZ = self.VBEZB.divide_exact(ZAHL100).subtract(self.FVB).set_scale(2, Round::Down);
            if (self.FVBZ.compare_to(self.HFVBZ) == 1) {
                self.FVBZ = self.HFVBZ.set_scale(0, Round::Up);
            }
        }
        self.MRE4ALTE();
    }

    fn MRE4ALTE(&mut self) {
        if (self.ALTER1 == 0) {
            self.ALTE = Dec::ZERO;
        } else {
            if (self.AJAHR < 2006) {
                self.K = 1;
            } else {
                if (self.AJAHR < 2058) {
                    self.K = (self.AJAHR - 2004);
                } else {
                    self.K = 54;
                }
            }
            self.BMG = self.ZRE4J.subtract(self.ZVBEZJ);
            self.ALTE = self.BMG.multiply(TAB4[self.K as usize]).set_scale(0, Round::Up);
            self.HBALTE = TAB5[self.K as usize];
            if (self.ALTE.compare_to(self.HBALTE) == 1) {
                self.ALTE = self.HBALTE;
            }
        }
    }

    fn MRE4ABZ(&mut self) {
        self.ZRE4 = self
            .ZRE4J
            .subtract(self.FVB)
            .subtract(self.ALTE)
            .subtract(self.JLFREIB)
            .add(self.JLHINZU)
            .set_scale(2, Round::Down);
        if (self.ZRE4.compare_to(Dec::ZERO) == -1) {
            self.ZRE4 = Dec::ZERO;
        }
        self.ZRE4VP = self.ZRE4J;
        self.ZVBEZ = self.ZVBEZJ.subtract(self.FVB).set_scale(2, Round::Down);
        if (self.ZVBEZ.compare_to(Dec::ZERO) == -1) {
            self.ZVBEZ = Dec::ZERO;
        }
    }

    fn MBERECH(&mut self) {
        self.MZTABFB();
        self.VFRB = self.ANP.add(self.FVB.add(self.FVBZ)).multiply(ZAHL100).set_scale(0, Round::Down);
        self.MLSTJAHR();
        self.WVFRB = self.ZVE.subtract(self.GFB).multiply(ZAHL100).set_scale(0, Round::Down);
        if (self.WVFRB.compare_to(Dec::ZERO) == -1) {
            self.WVFRB = Dec::ZERO;
        }
        self.LSTJAHR = self.ST.multiply(Dec::of(self.f)).set_scale(0, Round::Down);
        self.UPLSTLZZ();
        if (self.ZKF.compare_to(Dec::ZERO) == 1) {
            self.ZTABFB = self.ZTABFB.add(self.KFB);
            self.MRE4ABZ();
            self.MLSTJAHR();
            self.JBMG = self.ST.multiply(Dec::of(self.f)).set_scale(0, Round::Down);
        } else {
            self.JBMG = self.LSTJAHR;
        }
        self.MSOLZ();
    }

    fn MZTABFB(&mut self) {
        self.ANP = Dec::ZERO;
        if ((self.ZVBEZ.compare_to(Dec::ZERO) >= 0) && (self.ZVBEZ.compare_to(self.FVBZ) == -1)) {
            self.FVBZ = Dec::of(self.ZVBEZ.long_value());
        }
        if (self.STKL < 6) {
            if (self.ZVBEZ.compare_to(Dec::ZERO) == 1) {
                if (self.ZVBEZ.subtract(self.FVBZ).compare_to(Dec::lit(102, 0)) == -1) {
                    self.ANP = self.ZVBEZ.subtract(self.FVBZ).set_scale(0, Round::Up);
                } else {
                    self.ANP = Dec::lit(102, 0);
                }
            }
        } else {
            self.FVBZ = Dec::ZERO;
            self.FVBZSO = Dec::ZERO;
        }
        if (self.STKL < 6) {
            if (self.ZRE4.compare_to(self.ZVBEZ) == 1) {
                if (self.ZRE4.subtract(self.ZVBEZ).compare_to(Dec::lit(1230, 0)) == -1) {
                    self.ANP = self.ANP.add(self.ZRE4).subtract(self.ZVBEZ).set_scale(0, Round::Up);
                } else {
                    self.ANP = self.ANP.add(Dec::lit(1230, 0));
                }
            }
        }
        self.KZTAB = 1;
        if (self.STKL == 1) {
            self.SAP = Dec::lit(36, 0);
            self.KFB = self.ZKF.multiply(Dec::lit(9756, 0)).set_scale(0, Round::Down);
        } else {
            if (self.STKL == 2) {
                self.EFA = Dec::lit(4260, 0);
                self.SAP = Dec::lit(36, 0);
                self.KFB = self.ZKF.multiply(Dec::lit(9756, 0)).set_scale(0, Round::Down);
            } else {
                if (self.STKL == 3) {
                    self.KZTAB = 2;
                    self.SAP = Dec::lit(36, 0);
                    self.KFB = self.ZKF.multiply(Dec::lit(9756, 0)).set_scale(0, Round::Down);
                } else {
                    if (self.STKL == 4) {
                        self.SAP = Dec::lit(36, 0);
                        self.KFB = self.ZKF.multiply(Dec::lit(4878, 0)).set_scale(0, Round::Down);
                    } else {
                        if (self.STKL == 5) {
                            self.SAP = Dec::lit(36, 0);
                            self.KFB = Dec::ZERO;
                        } else {
                            self.KFB = Dec::ZERO;
                        }
                    }
                }
            }
        }
        self.ZTABFB = self.EFA.add(self.ANP).add(self.SAP).add(self.FVBZ).set_scale(2, Round::Down);
    }

    fn MLSTJAHR(&mut self) {
        self.UPEVP();
        self.ZVE = self.ZRE4.subtract(self.ZTABFB).subtract(self.VSP);
        self.UPMLST();
    }

    fn UPLSTLZZ(&mut self) {
        self.JW = self.LSTJAHR.multiply(ZAHL100);
        self.UPANTEIL();
        self.LSTLZZ = self.ANTEIL1;
    }

    fn UPMLST(&mut self) {
        if (self.ZVE.compare_to(ZAHL1) == -1) {
            self.ZVE = Dec::ZERO;
            self.X = Dec::ZERO;
        } else {
            self.X = self.ZVE.divide_exact(Dec::of(self.KZTAB)).set_scale(0, Round::Down);
        }
        if (self.STKL < 5) {
            self.UPTAB26();
        } else {
            self.MST5_6();
        }
    }

    fn UPEVP(&mut self) {
        if (self.KRV == 1) {
            self.VSPR = Dec::ZERO;
        } else {
            if (self.ZRE4VP.compare_to(self.BBGRVALV) == 1) {
                self.ZRE4VPR = self.BBGRVALV;
            } else {
                self.ZRE4VPR = self.ZRE4VP;
            }
            self.VSPR = self.ZRE4VPR.multiply(self.RVSATZAN).set_scale(2, Round::Down);
        }
        self.MVSPKVPV();
        if (self.ALV == 1) {
        } else {
            if (self.STKL == 6) {
            } else {
                self.MVSPHB();
            }
        }
    }

    fn MVSPKVPV(&mut self) {
        if (self.ZRE4VP.compare_to(self.BBGKVPV) == 1) {
            self.ZRE4VPR = self.BBGKVPV;
        } else {
            self.ZRE4VPR = self.ZRE4VP;
        }
        if (self.PKV > 0) {
            if (self.STKL == 6) {
                self.VSPKVPV = Dec::ZERO;
            } else {
                self.PKPVAGZJ = self.PKPVAGZ.multiply(ZAHL12).divide_exact(ZAHL100).set_scale(2, Round::Down);
                self.VSPKVPV = self.PKPV.multiply(ZAHL12).divide_exact(ZAHL100).set_scale(2, Round::Down);
                self.VSPKVPV = self.VSPKVPV.subtract(self.PKPVAGZJ);
                if (self.VSPKVPV.compare_to(Dec::ZERO) == -1) {
                    self.VSPKVPV = Dec::ZERO;
                }
            }
        } else {
            self.VSPKVPV = self.ZRE4VPR.multiply(self.KVSATZAN.add(self.PVSATZAN)).set_scale(2, Round::Down);
        }
        self.VSP = self.VSPKVPV.add(self.VSPR).set_scale(0, Round::Up);
    }

    fn MVSPHB(&mut self) {
        if (self.ZRE4VP.compare_to(self.BBGRVALV) == 1) {
            self.ZRE4VPR = self.BBGRVALV;
        } else {
            self.ZRE4VPR = self.ZRE4VP;
        }
        self.VSPALV = self.AVSATZAN.multiply(self.ZRE4VPR).set_scale(2, Round::Down);
        self.VSPHB = self.VSPALV.add(self.VSPKVPV).set_scale(2, Round::Down);
        if (self.VSPHB.compare_to(Dec::lit(1900, 0)) == 1) {
            self.VSPHB = Dec::lit(1900, 0);
        }
        self.VSPN = self.VSPR.add(self.VSPHB).set_scale(0, Round::Up);
        if (self.VSPN.compare_to(self.VSP) == 1) {
            self.VSP = self.VSPN;
        }
    }

    fn MST5_6(&mut self) {
        self.ZZX = self.X;
        if (self.ZZX.compare_to(self.W2STKL5) == 1) {
            self.ZX = self.W2STKL5;
            self.UP5_6();
            if (self.ZZX.compare_to(self.W3STKL5) == 1) {
                self.ST = self
                    .ST
                    .add(self.W3STKL5.subtract(self.W2STKL5).multiply(Dec::lit(42, 2)))
                    .set_scale(0, Round::Down);
                self.ST =
                    self.ST.add(self.ZZX.subtract(self.W3STKL5).multiply(Dec::lit(45, 2))).set_scale(0, Round::Down);
            } else {
                self.ST =
                    self.ST.add(self.ZZX.subtract(self.W2STKL5).multiply(Dec::lit(42, 2))).set_scale(0, Round::Down);
            }
        } else {
            self.ZX = self.ZZX;
            self.UP5_6();
            if (self.ZZX.compare_to(self.W1STKL5) == 1) {
                self.VERGL = self.ST;
                self.ZX = self.W1STKL5;
                self.UP5_6();
                self.HOCH =
                    self.ST.add(self.ZZX.subtract(self.W1STKL5).multiply(Dec::lit(42, 2))).set_scale(0, Round::Down);
                if (self.HOCH.compare_to(self.VERGL) == -1) {
                    self.ST = self.HOCH;
                } else {
                    self.ST = self.VERGL;
                }
            }
        }
    }

    fn UP5_6(&mut self) {
        self.X = self.ZX.multiply(Dec::lit(125, 2)).set_scale(0, Round::Down);
        self.UPTAB26();
        self.ST1 = self.ST;
        self.X = self.ZX.multiply(Dec::lit(75, 2)).set_scale(0, Round::Down);
        self.UPTAB26();
        self.ST2 = self.ST;
        self.DIFF = self.ST1.subtract(self.ST2).multiply(ZAHL2);
        self.MIST = self.ZX.multiply(Dec::lit(14, 2)).set_scale(0, Round::Down);
        if (self.MIST.compare_to(self.DIFF) == 1) {
            self.ST = self.MIST;
        } else {
            self.ST = self.DIFF;
        }
    }

    fn MSOLZ(&mut self) {
        self.SOLZFREI = self.SOLZFREI.multiply(Dec::of(self.KZTAB));
        if (self.JBMG.compare_to(self.SOLZFREI) == 1) {
            self.SOLZJ = self.JBMG.multiply(Dec::lit(55, 1)).divide_exact(ZAHL100).set_scale(2, Round::Down);
            self.SOLZMIN = self
                .JBMG
                .subtract(self.SOLZFREI)
                .multiply(Dec::lit(119, 1))
                .divide_exact(ZAHL100)
                .set_scale(2, Round::Down);
            if (self.SOLZMIN.compare_to(self.SOLZJ) == -1) {
                self.SOLZJ = self.SOLZMIN;
            }
            self.JW = self.SOLZJ.multiply(ZAHL100).set_scale(0, Round::Down);
            self.UPANTEIL();
            self.SOLZLZZ = self.ANTEIL1;
        } else {
            self.SOLZLZZ = Dec::ZERO;
        }
        if (self.R > 0) {
            self.JW = self.JBMG.multiply(ZAHL100);
            self.UPANTEIL();
            self.BK = self.ANTEIL1;
        } else {
            self.BK = Dec::ZERO;
        }
    }

    fn UPANTEIL(&mut self) {
        if (self.LZZ == 1) {
            self.ANTEIL1 = self.JW;
        } else {
            if (self.LZZ == 2) {
                self.ANTEIL1 = self.JW.divide(ZAHL12, 0, Round::Down);
            } else {
                if (self.LZZ == 3) {
                    self.ANTEIL1 = self.JW.multiply(ZAHL7).divide(ZAHL360, 0, Round::Down);
                } else {
                    self.ANTEIL1 = self.JW.divide(ZAHL360, 0, Round::Down);
                }
            }
        }
    }

    fn MSONST(&mut self) {
        self.LZZ = 1;
        if (self.ZMVB == 0) {
            self.ZMVB = 12;
        }
        if ((self.SONSTB.compare_to(Dec::ZERO) == 0) && (self.MBV.compare_to(Dec::ZERO) == 0)) {
            self.LSTSO = Dec::ZERO;
            self.STS = Dec::ZERO;
            self.SOLZS = Dec::ZERO;
            self.BKS = Dec::ZERO;
        } else {
            self.MOSONST();
            self.ZRE4J = self.JRE4.add(self.SONSTB).divide_exact(ZAHL100).set_scale(2, Round::Down);
            self.ZVBEZJ = self.JVBEZ.add(self.VBS).divide_exact(ZAHL100).set_scale(2, Round::Down);
            self.VBEZBSO = self.STERBE;
            self.MRE4SONST();
            self.MLSTJAHR();
            self.WVFRBM = self.ZVE.subtract(self.GFB).multiply(ZAHL100).set_scale(2, Round::Down);
            if (self.WVFRBM.compare_to(Dec::ZERO) == -1) {
                self.WVFRBM = Dec::ZERO;
            }
            self.LSTSO = self.ST.multiply(ZAHL100);
            self.STS = self
                .LSTSO
                .subtract(self.LSTOSO)
                .multiply(Dec::of(self.f))
                .divide(ZAHL100, 0, Round::Down)
                .multiply(ZAHL100);
            self.STSMIN();
        }
    }

    fn STSMIN(&mut self) {
        if (self.STS.compare_to(Dec::ZERO) == -1) {
            if (self.MBV.compare_to(Dec::ZERO) == 0) {
            } else {
                self.LSTLZZ = self.LSTLZZ.add(self.STS);
                if (self.LSTLZZ.compare_to(Dec::ZERO) == -1) {
                    self.LSTLZZ = Dec::ZERO;
                }
                self.SOLZLZZ = self
                    .SOLZLZZ
                    .add(self.STS.multiply(Dec::lit(55, 1).divide_exact(ZAHL100)))
                    .set_scale(0, Round::Down);
                if (self.SOLZLZZ.compare_to(Dec::ZERO) == -1) {
                    self.SOLZLZZ = Dec::ZERO;
                }
                self.BK = self.BK.add(self.STS);
                if (self.BK.compare_to(Dec::ZERO) == -1) {
                    self.BK = Dec::ZERO;
                }
            }
            self.STS = Dec::ZERO;
            self.SOLZS = Dec::ZERO;
        } else {
            self.MSOLZSTS();
        }
        if (self.R > 0) {
            self.BKS = self.STS;
        } else {
            self.BKS = Dec::ZERO;
        }
    }

    fn MSOLZSTS(&mut self) {
        if (self.ZKF.compare_to(Dec::ZERO) == 1) {
            self.SOLZSZVE = self.ZVE.subtract(self.KFB);
        } else {
            self.SOLZSZVE = self.ZVE;
        }
        if (self.SOLZSZVE.compare_to(Dec::ONE) == -1) {
            self.SOLZSZVE = Dec::ZERO;
            self.X = Dec::ZERO;
        } else {
            self.X = self.SOLZSZVE.divide(Dec::of(self.KZTAB), 0, Round::Down);
        }
        if (self.STKL < 5) {
            self.UPTAB26();
        } else {
            self.MST5_6();
        }
        self.SOLZSBMG = self.ST.multiply(Dec::of(self.f)).set_scale(0, Round::Down);
        if (self.SOLZSBMG.compare_to(self.SOLZFREI) == 1) {
            self.SOLZS = self.STS.multiply(Dec::lit(55, 1)).divide(ZAHL100, 0, Round::Down);
        } else {
            self.SOLZS = Dec::ZERO;
        }
    }

    fn MOSONST(&mut self) {
        self.ZRE4J = self.JRE4.divide_exact(ZAHL100).set_scale(2, Round::Down);
        self.ZVBEZJ = self.JVBEZ.divide_exact(ZAHL100).set_scale(2, Round::Down);
        self.JLFREIB = self.JFREIB.divide(ZAHL100, 2, Round::Down);
        self.JLHINZU = self.JHINZU.divide(ZAHL100, 2, Round::Down);
        self.MRE4();
        self.MRE4ABZ();
        self.ZRE4VP = self.ZRE4VP.subtract(self.JRE4ENT.divide_exact(ZAHL100));
        self.MZTABFB();
        self.VFRBS1 = self.ANP.add(self.FVB.add(self.FVBZ)).multiply(ZAHL100).set_scale(2, Round::Down);
        self.MLSTJAHR();
        self.WVFRBO = self.ZVE.subtract(self.GFB).multiply(ZAHL100).set_scale(2, Round::Down);
        if (self.WVFRBO.compare_to(Dec::ZERO) == -1) {
            self.WVFRBO = Dec::ZERO;
        }
        self.LSTOSO = self.ST.multiply(ZAHL100);
    }

    fn MRE4SONST(&mut self) {
        self.MRE4();
        self.FVB = self.FVBSO;
        self.MRE4ABZ();
        self.ZRE4VP = self
            .ZRE4VP
            .add(self.MBV.divide_exact(ZAHL100))
            .subtract(self.JRE4ENT.divide_exact(ZAHL100))
            .subtract(self.SONSTENT.divide_exact(ZAHL100));
        self.FVBZ = self.FVBZSO;
        self.MZTABFB();
        self.VFRBS2 = self.ANP.add(self.FVB).add(self.FVBZ).multiply(ZAHL100).subtract(self.VFRBS1);
    }

    fn UPTAB26(&mut self) {
        if (self.X.compare_to(self.GFB.add(ZAHL1)) == -1) {
            self.ST = Dec::ZERO;
        } else {
            if (self.X.compare_to(Dec::lit(17800, 0)) == -1) {
                self.Y = self.X.subtract(self.GFB).divide(ZAHL10000, 6, Round::Down);
                self.RW = self.Y.multiply(Dec::lit(91451, 2));
                self.RW = self.RW.add(Dec::lit(1400, 0));
                self.ST = self.RW.multiply(self.Y).set_scale(0, Round::Down);
            } else {
                if (self.X.compare_to(Dec::lit(69879, 0)) == -1) {
                    self.Y = self.X.subtract(Dec::lit(17799, 0)).divide(ZAHL10000, 6, Round::Down);
                    self.RW = self.Y.multiply(Dec::lit(1731, 1));
                    self.RW = self.RW.add(Dec::lit(2397, 0));
                    self.RW = self.RW.multiply(self.Y);
                    self.ST = self.RW.add(Dec::lit(103487, 2)).set_scale(0, Round::Down);
                } else {
                    if (self.X.compare_to(Dec::lit(277826, 0)) == -1) {
                        self.ST =
                            self.X.multiply(Dec::lit(42, 2)).subtract(Dec::lit(1113563, 2)).set_scale(0, Round::Down);
                    } else {
                        self.ST =
                            self.X.multiply(Dec::lit(45, 2)).subtract(Dec::lit(1947038, 2)).set_scale(0, Round::Down);
                    }
                }
            }
        }
        self.ST = self.ST.multiply(Dec::of(self.KZTAB));
    }
